head.script:
scwin.setColumnID = function(obj) {
    //debugger;
    var column = {};
    var columnArr = [];
    var gridHeader = "",
        gridBody = "";
    //json의 첫번째 데이터에서 컬럼의 id와 개수 정보 확
    for (var k in obj[0]) {
        //dataList를 동적으로 만들기 위한 컬럼 정
        column = {};
        column["id"] = k;
        column["dataType"] = "text";
        columnArr.push(column);
        //gridView의 컬럼 정보 정의
        gridHeader += '<w2:column blockSelect="false" id="' + 'h' + k + '" style="height:20px" inputType="text" width="70" value="' + k + '" useFilter="true"></w2:column>';
        if (k == 'col1') {
            gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" useFilter="true"></w2:column>'
        } else {
            gridBody += '<w2:column blockSelect="false" id="' + k + '" style="height:20px" inputType="text" width="70" useFilter="true"></w2:column>'
        }
    }
    //gridView 정보 정의 
    //xml 형식을 정의 하면 <w2:gridView 에 xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" 포함 합니다.
    var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" scrollByColumn="false" id="gridView1" style="width: 300px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" ev:ongroupby="scwin.ongroupby" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" rowNumWidth="" >' +
        '<w2:header id="header1" style="">' +
        '<w2:row id="row1" style="">' +
        gridHeader +
        '</w2:row>' +
        '</w2:header>' +
        '<w2:gBody id="gBody1" style="">' +
        '<w2:row id="row2" style="">' +
        gridBody +
        '</w2:row>' +
        '</w2:gBody>' +
        '</w2:gridView>';
    gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
    dataList1.setJSON(obj);
}
scwin.ongrp = function(options) {
    options.groupbyHeader = [];
    options.groupbyFooter = [];
    gridView1.groupby(options);
};
scwin.ongroupby = function(options) {
    options.groupbyHeader = [];
    options.groupbyFooter = [];
    options.hideFooter = true;
    this.groupby(options);
    return false;
}
scwin.___isCheckLog = function() {
    return WebSquare.logger.getErrorLog() == "";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_groupbyFilterBox_select_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. groupbyFilterBox에 'ALL'또는 '전체'부분이 나타나지 않는다.(기능개선 전에는 'ALL'또는 '전체'부분이 나타남)
    //1. 'ALL' or 'ALL' parts do not appear in groupbyFilterBox ('ALL' or 'ALL' parts appear before improvement)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_groupbyFilterBox_select_label').innerText != 'ALL'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_groupbyFilterBox_select_itemTable_0') == null", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.___isCheckLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
